-- Comments
comment on column public.orders.ship_state is 'State / province / region — optional at the DB level; required client-side in checkout when ship_country is US/CA/AU.';
comment on column public.orders.origin_offer_id is 'The accepted offer this order came from. NULL for buy-now and cart orders.';
comment on column public.orders.correlation_id is 'Groups the orders of one checkout and matches the Stripe PaymentIntent metadata correlation_id. Observability only — never a money-path key.';
comment on column public.orders.shipping_quote is 'DRVN Shipping service frozen at checkout (§15.7): provider, service, quoted amount, parcel. Null for flat/pickup orders.';
comment on column public.orders.pickup_ready_at is 'Seller marked this collection order ready for handoff (0054). Null for shipped orders.';
comment on column public.orders.dispatch_by is 'Frozen when the order became paid (20261107210300): paid + the seller''s handling business days. Shipping orders only.';
comment on column public.orders.deliver_by is 'Latest delivery date, frozen when paid: dispatch_by + transit business days (quote, else 5 domestic / 15 international). "Item never arrived" opens here.';
comment on column public.orders.available_by is 'Collection orders: when the item must be made available, frozen when paid (paid + handling business days).';
comment on column public.orders.dispute_respond_by is 'Seller response deadline: 3 business days after the report. Escalation opens here.';
comment on column public.orders.dispute_escalate_until is 'Last moment either party can escalate: 21 business days after the report.';
comment on column public.orders.refund_offer_expires_at is 'refund_offered_at + 48 hours, always (orders_freeze_deadlines). An expired offer cannot be accepted and does not block escalation.';

-- Constraints
alter table public.orders add constraint account_deletion_hold_watch TRIGGER DEFERRABLE INITIALLY DEFERRED;
alter table public.orders add constraint orders_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES public.profiles(id) ON DELETE SET NULL;
alter table public.orders add constraint orders_currency_usd CHECK (currency = 'USD'::text);
alter table public.orders add constraint orders_delivery_estimate_source_check CHECK (delivery_estimate_source IS NULL OR (delivery_estimate_source = ANY (ARRAY['quote'::text, 'fallback'::text, 'collection'::text])));
alter table public.orders add constraint orders_dispute_category_check CHECK (dispute_category IS NULL OR (dispute_category = ANY (ARRAY['item_not_received'::text, 'item_not_as_described'::text, 'damaged_in_transit'::text, 'wrong_item'::text, 'counterfeit'::text, 'does_not_fit'::text, 'other'::text])));
alter table public.orders add constraint orders_dispute_escalated_by_fkey FOREIGN KEY (dispute_escalated_by) REFERENCES public.profiles(id) ON DELETE SET NULL;
alter table public.orders add constraint orders_dispute_outcome_check CHECK (dispute_outcome IS NULL OR (dispute_outcome = ANY (ARRAY['refund_accepted'::text, 'closed_by_buyer'::text, 'auto_refunded'::text, 'admin_refunded'::text, 'admin_resolved'::text, 'chargeback_lost'::text])));
alter table public.orders add constraint orders_disputed_by_fkey FOREIGN KEY (disputed_by) REFERENCES public.profiles(id) ON DELETE SET NULL;
alter table public.orders add constraint orders_origin_offer_id_fkey FOREIGN KEY (origin_offer_id) REFERENCES public.offers(id) ON DELETE SET NULL;
alter table public.orders add constraint orders_pkey PRIMARY KEY (id);
alter table public.orders add constraint orders_refund_offer_cents_check CHECK (refund_offer_cents IS NULL OR refund_offer_cents > 0 AND refund_offer_cents <= total_cents);
alter table public.orders add constraint orders_refunded_cents_check CHECK (refunded_cents >= 0 AND refunded_cents <= total_cents AND platform_fee_refunded_cents >= 0 AND platform_fee_refunded_cents <= platform_fee_cents);
alter table public.orders add constraint orders_seller_id_fkey FOREIGN KEY (seller_id) REFERENCES public.profiles(id) ON DELETE SET NULL;
alter table public.orders add constraint orders_status_check CHECK (status = ANY (ARRAY['pending'::text, 'requires_action'::text, 'payment_failed'::text, 'paid'::text, 'shipped'::text, 'delivered'::text, 'completed'::text, 'cancelled'::text, 'refunded'::text, 'disputed'::text]));

